{
  "name": "agentmarvin",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "description": "AgentMarvin — retro raycaster FPS that onboards developers to Entire. Milestone 0: engine skeleton.",
  "scripts": {
    "dev": "vite",
    "build": "tsc --noEmit && vite build",
    "preview": "vite preview",
    "test": "vitest run",
    "test:watch": "vitest",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "typescript": "^5.6.3",
    "vite": "^5.4.10",
    "vitest": "^2.1.4"
  }
}

import { defineConfig } from 'vite';

// AgentMarvin M0 — plain Vite + TS, no framework. Maps are served as static JSON
// from /maps and fetched at runtime so designers/modders can edit them without a rebuild.
export default defineConfig({
  root: '.',
  publicDir: 'maps' === 'maps' ? 'public' : 'public',
  build: {
    target: 'es2022',
    outDir: 'dist',
    sourcemap: true,
  },
  test: {
    environment: 'node',
    include: ['test/**/*.test.ts'],
  },
});

/// <reference types="vitest/config" />
import { defineConfig } from 'vite';

// AgentMarvin M0 — plain Vite + TS, no framework.
// Map JSON lives in /public/maps and is fetched at runtime so designers/modders
// can edit levels without a rebuild (see docs/11-technical-spec.md).
export default defineConfig({
  root: '.',
  publicDir: 'public',
  build: {
    target: 'es2022',
    outDir: 'dist',
    sourcemap: true,
  },
  test: {
    environment: 'node',
    include: ['test/**/*.test.ts'],
  },
});

// Shared types for AgentMarvin M0.
// The map schema mirrors docs/11-technical-spec.md exactly so later milestones
// (Sessions, Trails, Gates) need no format change. Fields not used in M0 are
// parsed and kept but otherwise inert.

/** A 2D grid position in tile coordinates. */
export type Vec2 = { x: number; y: number };

/** Tile ids used by the raycaster. 0 = empty/floor; >0 = solid wall variants. */
export type TileId = number;

export interface MapGrid {
  width: number;
  height: number;
  /** Row-major array of length width*height. */
  tiles: TileId[];
}

export interface MapDoor {
  /** [x, y] tile the door occupies. */
  at: [number, number];
  label?: string;
  /** M0: doors open on interact regardless of `locked`. Lock logic lands in M1. */
  locked?: boolean;
  opensVia?: string;
}

/** Entity as authored in the map JSON. `type` drives which sprite is drawn. */
export interface MapEntity {
  type: string;
  /** [x, y] in tile coordinates (may be fractional). */
  at: [number, number];
  /** Whether a hallucination is real (M1 mechanic); parsed now, unused in M0. */
  real?: boolean;
  item?: string;
  sessionId?: string;
  requiresEvidence?: number;
}

/** Recorded action log for a Session ghost. Parsed but unused in M0. */
export interface MapSession {
  id: string;
  actions: unknown[];
}

/** Lineage edge for the Trail Beacon. Parsed but unused in M0. */
export interface MapTrail {
  effect: string;
  causes: string[];
}

/** The on-disk level format (docs/11-technical-spec.md#map-data-format-json). */
export interface GameMap {
  id: string;
  region: string;
  palette: string;
  grid: MapGrid;
  doors?: MapDoor[];
  entities?: MapEntity[];
  sessions?: MapSession[];
  trails?: MapTrail[];
  trustStart?: number;
}

/** Runtime player state (position + facing). */
export interface Player {
  /** World position in tile units (e.g. 3.5 = middle of tile 3). */
  pos: Vec2;
  /** Facing direction unit vector. */
  dir: Vec2;
  /** Camera plane, perpendicular to dir; its length sets the FOV. */
  plane: Vec2;
}

// Seeded, deterministic RNG (mulberry32). Determinism matters for tests now and
// for co-op sync / Session replay later (docs/11-technical-spec.md).

export class Rng {
  private state: number;

  constructor(seed: number) {
    // Force to a 32-bit unsigned integer state.
    this.state = seed >>> 0;
  }

  /** Next float in [0, 1). */
  next(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  /** Integer in [min, max] inclusive. */
  int(min: number, max: number): number {
    return min + Math.floor(this.next() * (max - min + 1));
  }

  /** Float in [min, max). */
  range(min: number, max: number): number {
    return min + this.next() * (max - min);
  }
}

// Keyboard + mouse input for AgentMarvin M0.
// Movement is Pointer-Lock mouse-look + WASD/arrows. Bindings are a map so they
// can be remapped later (docs/08 accessibility: remappable controls).

export type Action = 'forward' | 'back' | 'left' | 'right' | 'interact';

const DEFAULT_BINDINGS: Record<string, Action> = {
  KeyW: 'forward',
  ArrowUp: 'forward',
  KeyS: 'back',
  ArrowDown: 'back',
  KeyA: 'left',
  ArrowLeft: 'left',
  KeyD: 'right',
  ArrowRight: 'right',
  KeyE: 'interact',
};

export class Input {
  private held = new Set<Action>();
  private bindings: Record<string, Action>;
  private pressedThisFrame = new Set<Action>();
  /** Accumulated mouse-X delta (radians of yaw) since the last consume. */
  private mouseDx = 0;
  private locked = false;

  /** Mouse sensitivity: radians of yaw per pixel of movement. */
  sensitivity = 0.0022;

  constructor(
    private readonly canvas: HTMLCanvasElement,
    bindings: Record<string, Action> = DEFAULT_BINDINGS,
  ) {
    this.bindings = bindings;
  }

  /** Callback fired the first time the pointer is locked (used to unblock audio). */
  onFirstLock: (() => void) | null = null;
  private hasLockedOnce = false;

  attach(): void {
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    this.canvas.addEventListener('click', this.requestLock);
    document.addEventListener('pointerlockchange', this.onLockChange);
    document.addEventListener('mousemove', this.onMouseMove);
  }

  detach(): void {
    window.removeEventListener('keydown', this.onKeyDown);
    window.removeEventListener('keyup', this.onKeyUp);
    this.canvas.removeEventListener('click', this.requestLock);
    document.removeEventListener('pointerlockchange', this.onLockChange);
    document.removeEventListener('mousemove', this.onMouseMove);
  }

  isDown(action: Action): boolean {
    return this.held.has(action);
  }

  /** True once per press; consumed on read (edge trigger, e.g. door interact). */
  wasPressed(action: Action): boolean {
    if (this.pressedThisFrame.has(action)) {
      this.pressedThisFrame.delete(action);
      return true;
    }
    return false;
  }

  get isLocked(): boolean {
    return this.locked;
  }

  /** Consume and return accumulated mouse yaw delta since last call. */
  consumeMouseDx(): number {
    const dx = this.mouseDx;
    this.mouseDx = 0;
    return dx;
  }

  private requestLock = (): void => {
    void this.canvas.requestPointerLock();
  };

  private onLockChange = (): void => {
    this.locked = document.pointerLockElement === this.canvas;
    if (this.locked && !this.hasLockedOnce) {
      this.hasLockedOnce = true;
      this.onFirstLock?.();
    }
    if (!this.locked) {
      // Dropping lock releases all keys so we don't get stuck moving.
      this.held.clear();
    }
  };

  private onMouseMove = (e: MouseEvent): void => {
    if (!this.locked) return;
    this.mouseDx += e.movementX * this.sensitivity;
  };

  private onKeyDown = (e: KeyboardEvent): void => {
    const action = this.bindings[e.code];
    if (!action) return;
    if (!this.held.has(action)) this.pressedThisFrame.add(action);
    this.held.add(action);
    e.preventDefault();
  };

  private onKeyUp = (e: KeyboardEvent): void => {
    const action = this.bindings[e.code];
    if (!action) return;
    this.held.delete(action);
    e.preventDefault();
  };
}

// Fixed-timestep game loop (docs/11-technical-spec.md: sim @60Hz, render decoupled).
// The simulation advances in fixed 1/60s steps for deterministic, framerate-
// independent movement ("Movement First" pillar). Rendering runs once per rAF and
// receives an interpolation alpha for smoothness on high-refresh displays.

export interface LoopCallbacks {
  /** Advance the simulation by a fixed dt (seconds). */
  update(dt: number): void;
  /** Draw a frame. `alpha` in [0,1) interpolates between the last two sim steps. */
  render(alpha: number): void;
  /** Optional per-frame FPS report. */
  onFps?(fps: number): void;
}

export class GameLoop {
  private readonly step = 1 / 60; // fixed sim timestep in seconds
  private readonly maxFrame = 0.25; // clamp to avoid spiral-of-death after tab-out
  private accumulator = 0;
  private lastTime = 0;
  private running = false;
  private rafId = 0;

  // FPS tracking over a rolling ~0.5s window.
  private fpsAccum = 0;
  private fpsFrames = 0;

  constructor(private readonly cb: LoopCallbacks) {}

  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastTime = performance.now();
    this.rafId = requestAnimationFrame(this.frame);
  }

  stop(): void {
    this.running = false;
    cancelAnimationFrame(this.rafId);
  }

  private frame = (now: number): void => {
    if (!this.running) return;
    let frameTime = (now - this.lastTime) / 1000;
    this.lastTime = now;
    if (frameTime > this.maxFrame) frameTime = this.maxFrame;

    this.accumulator += frameTime;
    while (this.accumulator >= this.step) {
      this.cb.update(this.step);
      this.accumulator -= this.step;
    }

    const alpha = this.accumulator / this.step;
    this.cb.render(alpha);

    // FPS meter.
    this.fpsAccum += frameTime;
    this.fpsFrames++;
    if (this.fpsAccum >= 0.5) {
      this.cb.onFps?.(this.fpsFrames / this.fpsAccum);
      this.fpsAccum = 0;
      this.fpsFrames = 0;
    }

    this.rafId = requestAnimationFrame(this.frame);
  };
}

// 320x200 software framebuffer, integer-scaled to the canvas (docs/08, docs/11).
// Pixels are packed as 32-bit little-endian ABGR (the memory layout the browser's
// ImageData expects on little-endian machines), so a single set of the underlying
// Uint32Array maps directly to an RGBA pixel.

export const SCREEN_W = 320;
export const SCREEN_H = 200;

/** Pack r,g,b,a (0-255) into the 0xAABBGGRR word ImageData expects. */
export function rgba(r: number, g: number, b: number, a = 255): number {
  return ((a << 24) | (b << 16) | (g << 8) | r) >>> 0;
}

/** Scale each channel of a packed color by t in [0,1] (cheap distance shading). */
export function shade(color: number, t: number): number {
  const r = (color & 0xff) * t;
  const g = ((color >> 8) & 0xff) * t;
  const b = ((color >> 16) & 0xff) * t;
  const a = (color >> 24) & 0xff;
  return rgba(r | 0, g | 0, b | 0, a);
}

export class Framebuffer {
  readonly width = SCREEN_W;
  readonly height = SCREEN_H;
  /** Packed ABGR pixels, row-major, length width*height. */
  readonly buf: Uint32Array;
  private readonly imageData: ImageData;
  private readonly u32View: Uint32Array;
  private readonly ctx: CanvasRenderingContext2D;

  constructor(canvas: HTMLCanvasElement) {
    canvas.width = SCREEN_W;
    canvas.height = SCREEN_H;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) throw new Error('2D canvas context unavailable');
    this.ctx = ctx;
    this.ctx.imageSmoothingEnabled = false;
    this.imageData = ctx.createImageData(SCREEN_W, SCREEN_H);
    // View the ImageData bytes as 32-bit words so we can blit in one copy.
    this.u32View = new Uint32Array(this.imageData.data.buffer);
    this.buf = new Uint32Array(SCREEN_W * SCREEN_H);
  }

  /** Fill the whole buffer with a packed color. */
  clear(color: number): void {
    this.buf.fill(color);
  }

  /** Fill a vertical span of a column [y0, y1) with a solid color. */
  vspan(x: number, y0: number, y1: number, color: number): void {
    if (x < 0 || x >= SCREEN_W) return;
    const top = Math.max(0, y0 | 0);
    const bottom = Math.min(SCREEN_H, y1 | 0);
    for (let y = top; y < bottom; y++) {
      this.buf[y * SCREEN_W + x] = color;
    }
  }

  setPixel(x: number, y: number, color: number): void {
    if (x < 0 || x >= SCREEN_W || y < 0 || y >= SCREEN_H) return;
    this.buf[y * SCREEN_W + x] = color;
  }

  /** Copy the software buffer to the canvas. Canvas CSS scaling does the upscale. */
  present(): void {
    this.u32View.set(this.buf);
    this.ctx.putImageData(this.imageData, 0, 0);
  }

  /** Size the canvas element on screen to the largest integer multiple that fits. */
  static fitCanvas(canvas: HTMLCanvasElement): void {
    const scaleX = Math.floor(window.innerWidth / SCREEN_W);
    const scaleY = Math.floor(window.innerHeight / SCREEN_H);
    const scale = Math.max(1, Math.min(scaleX, scaleY));
    canvas.style.width = `${SCREEN_W * scale}px`;
    canvas.style.height = `${SCREEN_H * scale}px`;
  }
}

// Procedural programmer-art textures (no asset files) — generated at boot into
// small offscreen buffers, keyed by the map's `palette` (docs/08, docs/11).
// Walls are indexed by tile id; sprites by entity `type`.

import { rgba } from './framebuffer';
import { Rng } from '../core/rng';

export const TEX_SIZE = 64;

export interface Texture {
  width: number;
  height: number;
  /** Packed ABGR; a=0 means transparent (used by sprites). */
  data: Uint32Array;
}

interface Palette {
  ceiling: number;
  floor: number;
  /** Base color per wall tile id (index 1..n). Index 0 unused (empty tile). */
  walls: number[];
  door: number;
  accent: number;
}

const PALETTES: Record<string, Palette> = {
  // Session Archive — solemn cool blue (docs/01).
  'cool-blue': {
    ceiling: rgba(10, 14, 28),
    floor: rgba(18, 22, 40),
    walls: [0, rgba(40, 60, 110), rgba(56, 80, 140)],
    door: rgba(90, 150, 210),
    accent: rgba(124, 255, 178),
  },
  // Working Directory — unstable green terminal (docs/01, docs/08 neon).
  'working-directory': {
    ceiling: rgba(6, 10, 8),
    floor: rgba(12, 20, 16),
    walls: [0, rgba(30, 70, 50), rgba(44, 92, 66)],
    door: rgba(70, 200, 130),
    accent: rgba(124, 255, 178),
  },
};

function palette(name: string): Palette {
  return PALETTES[name] ?? PALETTES['working-directory']!;
}

function empty(w: number, h: number): Texture {
  return { width: w, height: h, data: new Uint32Array(w * h) };
}

/** Small deterministic per-channel jitter so flat surfaces get texture. */
function jitter(color: number, d: number): number {
  const r = Math.max(0, Math.min(255, (color & 0xff) + d));
  const g = Math.max(0, Math.min(255, ((color >> 8) & 0xff) + d));
  const b = Math.max(0, Math.min(255, ((color >> 16) & 0xff) + d));
  return rgba(r, g, b);
}

/** Brick-ish wall texture with mortar lines and grain. */
function makeWall(base: number, mortar: number, rng: Rng): Texture {
  const t = empty(TEX_SIZE, TEX_SIZE);
  const brickH = 16;
  const brickW = 32;
  for (let y = 0; y < TEX_SIZE; y++) {
    const row = Math.floor(y / brickH);
    const offset = (row % 2) * (brickW / 2);
    for (let x = 0; x < TEX_SIZE; x++) {
      const inMortarY = y % brickH < 2;
      const inMortarX = (x + offset) % brickW < 2;
      let c: number;
      if (inMortarY || inMortarX) {
        c = mortar;
      } else {
        c = jitter(base, rng.int(-12, 12));
      }
      t.data[y * TEX_SIZE + x] = c;
    }
  }
  return t;
}

/** Door texture: paneled slab with a bright frame. */
function makeDoor(base: number, frame: number): Texture {
  const t = empty(TEX_SIZE, TEX_SIZE);
  for (let y = 0; y < TEX_SIZE; y++) {
    for (let x = 0; x < TEX_SIZE; x++) {
      const edge = x < 4 || x >= TEX_SIZE - 4 || y < 4 || y >= TEX_SIZE - 4;
      const panel = x > 12 && x < TEX_SIZE - 12 && y > 12 && y < TEX_SIZE - 12;
      t.data[y * TEX_SIZE + x] = edge ? frame : panel ? jitter(base, 18) : base;
    }
  }
  return t;
}

/** Radial glow sprite (Session Anchor / pickup). cx,cy center, r radius. */
function makeGlow(color: number, r: number): Texture {
  const size = 48;
  const t = empty(size, size);
  const cx = size / 2;
  const cy = size / 2;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const d = Math.hypot(x - cx, y - cy);
      if (d > r) continue;
      const k = 1 - d / r;
      const rr = Math.min(255, (color & 0xff) * (0.4 + k));
      const gg = Math.min(255, ((color >> 8) & 0xff) * (0.4 + k));
      const bb = Math.min(255, ((color >> 16) & 0xff) * (0.4 + k));
      const a = Math.min(255, Math.floor(k * 320));
      t.data[y * size + x] = rgba(rr | 0, gg | 0, bb | 0, a);
    }
  }
  return t;
}

/** A little humanoid blob sprite (Hallucination Bot placeholder). */
function makeBot(color: number): Texture {
  const size = 48;
  const t = empty(size, size);
  const put = (x: number, y: number, c: number): void => {
    if (x >= 0 && x < size && y >= 0 && y < size) t.data[y * size + x] = c;
  };
  const eye = rgba(255, 60, 90);
  // Body ellipse.
  for (let y = 10; y < 44; y++) {
    for (let x = 12; x < 36; x++) {
      const nx = (x - 24) / 12;
      const ny = (y - 27) / 17;
      if (nx * nx + ny * ny <= 1) put(x, y, jitter(color, ((x + y) % 5) - 2));
    }
  }
  // Head.
  for (let y = 2; y < 16; y++) {
    for (let x = 17; x < 31; x++) {
      const nx = (x - 24) / 7;
      const ny = (y - 9) / 7;
      if (nx * nx + ny * ny <= 1) put(x, y, jitter(color, 8));
    }
  }
  // Glowing eyes.
  put(21, 9, eye);
  put(22, 9, eye);
  put(26, 9, eye);
  put(27, 9, eye);
  return t;
}

export interface TextureSet {
  ceiling: number;
  floor: number;
  /** Wall texture per tile id; index 0 is a dummy. */
  walls: Texture[];
  door: Texture;
  sprites: Map<string, Texture>;
}

/** Build all textures for a given palette name. Deterministic (seeded). */
export function buildTextures(paletteName: string): TextureSet {
  const p = palette(paletteName);
  const rng = new Rng(0x5eed ^ paletteName.length);
  const mortar = jitter(p.floor, -6);

  const walls: Texture[] = [empty(TEX_SIZE, TEX_SIZE)];
  for (let i = 1; i < p.walls.length; i++) {
    walls.push(makeWall(p.walls[i]!, mortar, rng));
  }

  const sprites = new Map<string, Texture>();
  sprites.set('session-anchor', makeGlow(rgba(90, 160, 255), 22));
  sprites.set('pickup', makeGlow(p.accent, 16));
  sprites.set('hallucination-bot', makeBot(rgba(150, 90, 200)));
  sprites.set('gate-node', makeGlow(rgba(255, 180, 80), 22));
  // Fallback marker for any unknown entity type.
  sprites.set('__default', makeGlow(rgba(200, 200, 200), 18));

  return {
    ceiling: p.ceiling,
    floor: p.floor,
    walls,
    door: makeDoor(p.door, p.accent),
    sprites,
  };
}

// DDA raycaster (docs/11). Renders textured wall columns into the framebuffer and
// writes a per-column depth buffer so sprites.ts can occlude billboards correctly.
//
// `castRay` is a pure function (grid solidity is injected) so it can be unit-tested
// without a browser.

import { Framebuffer, SCREEN_W, SCREEN_H, shade } from './framebuffer';
import { TEX_SIZE, type TextureSet } from './textures';
import type { Player } from '../world/types';

/** Sentinel tile id returned by `solidAt` for a closed door. */
export const DOOR_TILE = 99;

export interface RayHit {
  /** Perpendicular distance to the wall (avoids fisheye). */
  dist: number;
  /** 0 = hit an x-side (E/W face), 1 = hit a y-side (N/S face). */
  side: 0 | 1;
  /** The solid tile id that was hit (wall id, or DOOR_TILE). */
  tileId: number;
  /** Where along the wall face the ray hit, in [0,1). */
  wallX: number;
  mapX: number;
  mapY: number;
}

/**
 * March a single ray via DDA. `solidAt(x,y)` returns 0 if passable, else the solid
 * tile id. Returns null if no wall is hit within `maxSteps`.
 */
export function castRay(
  solidAt: (x: number, y: number) => number,
  posX: number,
  posY: number,
  rayDirX: number,
  rayDirY: number,
  maxSteps = 128,
): RayHit | null {
  let mapX = Math.floor(posX);
  let mapY = Math.floor(posY);

  const deltaDistX = rayDirX === 0 ? Infinity : Math.abs(1 / rayDirX);
  const deltaDistY = rayDirY === 0 ? Infinity : Math.abs(1 / rayDirY);

  let stepX: number;
  let stepY: number;
  let sideDistX: number;
  let sideDistY: number;

  if (rayDirX < 0) {
    stepX = -1;
    sideDistX = (posX - mapX) * deltaDistX;
  } else {
    stepX = 1;
    sideDistX = (mapX + 1 - posX) * deltaDistX;
  }
  if (rayDirY < 0) {
    stepY = -1;
    sideDistY = (posY - mapY) * deltaDistY;
  } else {
    stepY = 1;
    sideDistY = (mapY + 1 - posY) * deltaDistY;
  }

  let side: 0 | 1 = 0;
  for (let i = 0; i < maxSteps; i++) {
    if (sideDistX < sideDistY) {
      sideDistX += deltaDistX;
      mapX += stepX;
      side = 0;
    } else {
      sideDistY += deltaDistY;
      mapY += stepY;
      side = 1;
    }

    const tileId = solidAt(mapX, mapY);
    if (tileId > 0) {
      const dist =
        side === 0
          ? sideDistX - deltaDistX
          : sideDistY - deltaDistY;
      let wallX =
        side === 0 ? posY + dist * rayDirY : posX + dist * rayDirX;
      wallX -= Math.floor(wallX);
      return { dist: Math.max(1e-4, dist), side, tileId, wallX, mapX, mapY };
    }
  }
  return null;
}

/** Distance shading factor in (0,1]; nearer = brighter. */
function fog(dist: number): number {
  return Math.max(0.15, Math.min(1, 1 / (1 + dist * 0.18)));
}

/**
 * Render the wall layer. Fills ceiling/floor, then casts one ray per screen
 * column. `depth` is filled with each column's perpendicular distance.
 */
export function renderWalls(
  fb: Framebuffer,
  player: Player,
  solidAt: (x: number, y: number) => number,
  tex: TextureSet,
  depth: Float32Array,
): void {
  const halfH = SCREEN_H >> 1;

  // Flat ceiling (top half) and floor (bottom half).
  for (let y = 0; y < halfH; y++) {
    const row = y * SCREEN_W;
    fb.buf.fill(tex.ceiling, row, row + SCREEN_W);
  }
  for (let y = halfH; y < SCREEN_H; y++) {
    const row = y * SCREEN_W;
    fb.buf.fill(tex.floor, row, row + SCREEN_W);
  }

  for (let x = 0; x < SCREEN_W; x++) {
    const cameraX = (2 * x) / SCREEN_W - 1;
    const rayDirX = player.dir.x + player.plane.x * cameraX;
    const rayDirY = player.dir.y + player.plane.y * cameraX;

    const hit = castRay(solidAt, player.pos.x, player.pos.y, rayDirX, rayDirY);
    if (!hit) {
      depth[x] = Infinity;
      continue;
    }
    depth[x] = hit.dist;

    const lineHeight = Math.floor(SCREEN_H / hit.dist);
    let drawStart = -(lineHeight >> 1) + halfH;
    let drawEnd = (lineHeight >> 1) + halfH;

    const texture = hit.tileId === DOOR_TILE ? tex.door : tex.walls[hit.tileId] ?? tex.walls[1]!;

    let texX = Math.floor(hit.wallX * TEX_SIZE);
    if (hit.side === 0 && rayDirX > 0) texX = TEX_SIZE - texX - 1;
    if (hit.side === 1 && rayDirY < 0) texX = TEX_SIZE - texX - 1;

    const step = TEX_SIZE / lineHeight;
    // Texture coordinate at the (clamped) top of the column.
    let texPos = (drawStart - halfH + (lineHeight >> 1)) * step;
    if (drawStart < 0) {
      texPos += -drawStart * step;
      drawStart = 0;
    }
    if (drawEnd > SCREEN_H) drawEnd = SCREEN_H;

    const shadeT = fog(hit.dist) * (hit.side === 1 ? 0.72 : 1);
    const col = texX;
    for (let y = drawStart; y < drawEnd; y++) {
      const texY = Math.min(TEX_SIZE - 1, texPos | 0);
      texPos += step;
      const c = texture.data[texY * TEX_SIZE + col]!;
      fb.buf[y * SCREEN_W + x] = shade(c, shadeT);
    }
  }
}

// Billboarded sprite rendering (docs/11). Sprites are projected with the inverse
// camera matrix, z-sorted far-to-near, and clipped per-column against the wall
// depth buffer so they're correctly occluded by geometry. Transparent texels
// (alpha 0) are skipped.

import { Framebuffer, SCREEN_W, SCREEN_H, shade } from './framebuffer';
import type { Texture } from './textures';
import type { Player, Vec2 } from '../world/types';

export interface SpriteInstance {
  pos: Vec2;
  texture: Texture;
}

/** Distance shading factor, matching the wall fog curve. */
function fog(dist: number): number {
  return Math.max(0.25, Math.min(1, 1 / (1 + dist * 0.18)));
}

export function renderSprites(
  fb: Framebuffer,
  player: Player,
  sprites: SpriteInstance[],
  depth: Float32Array,
): void {
  if (sprites.length === 0) return;

  // Sort by squared distance, far first (painter's order).
  const order = sprites
    .map((s, i) => {
      const dx = s.pos.x - player.pos.x;
      const dy = s.pos.y - player.pos.y;
      return { i, d2: dx * dx + dy * dy };
    })
    .sort((a, b) => b.d2 - a.d2);

  const invDet =
    1 / (player.plane.x * player.dir.y - player.dir.x * player.plane.y);
  const halfH = SCREEN_H >> 1;

  for (const { i } of order) {
    const sprite = sprites[i]!;
    const spriteX = sprite.pos.x - player.pos.x;
    const spriteY = sprite.pos.y - player.pos.y;

    // Camera-space transform. transformY is the depth (forward distance).
    const transformX =
      invDet * (player.dir.y * spriteX - player.dir.x * spriteY);
    const transformY =
      invDet * (-player.plane.y * spriteX + player.plane.x * spriteY);

    if (transformY <= 0.05) continue; // behind camera / too close

    const screenX = Math.floor((SCREEN_W / 2) * (1 + transformX / transformY));

    const spriteH = Math.abs(Math.floor(SCREEN_H / transformY));
    const spriteW = spriteH; // sprites authored square

    let drawStartY = -(spriteH >> 1) + halfH;
    let drawEndY = (spriteH >> 1) + halfH;
    const clipTop = drawStartY < 0 ? -drawStartY : 0;
    if (drawStartY < 0) drawStartY = 0;
    if (drawEndY > SCREEN_H) drawEndY = SCREEN_H;

    let drawStartX = -(spriteW >> 1) + screenX;
    let drawEndX = (spriteW >> 1) + screenX;
    if (drawStartX < 0) drawStartX = 0;
    if (drawEndX > SCREEN_W) drawEndX = SCREEN_W;

    const tw = sprite.texture.width;
    const th = sprite.texture.height;
    const shadeT = fog(transformY);
    const startXOffset = -(spriteW >> 1) + screenX;

    for (let x = drawStartX; x < drawEndX; x++) {
      // Occlusion: skip stripes hidden behind nearer walls.
      if (transformY >= depth[x]!) continue;
      const texX = Math.floor(((x - startXOffset) * tw) / spriteW);
      if (texX < 0 || texX >= tw) continue;

      for (let y = drawStartY; y < drawEndY; y++) {
        const texY = Math.floor(((y - halfH + (spriteH >> 1) + clipTop - clipTop) * th) / spriteH);
        if (texY < 0 || texY >= th) continue;
        const c = sprite.texture.data[texY * tw + texX]!;
        if ((c >>> 24) === 0) continue; // transparent
        fb.buf[y * SCREEN_W + x] = shade(c, shadeT);
      }
    }
  }
}

