// World: wraps a loaded GameMap with runtime state (door open/closed) and the
// queries the raycaster and collision need. Faithful to the doc-11 JSON schema.

import type { GameMap, TileId, Vec2 } from './types';
import { DOOR_TILE } from '../render/raycaster';

interface DoorState {
  open: boolean;
  label?: string;
  locked: boolean;
}

/** Parse + lightly validate a raw JSON object into a GameMap. Throws on bad shape. */
export function parseMap(raw: unknown): GameMap {
  const m = raw as Partial<GameMap>;
  if (!m || typeof m !== 'object') throw new Error('map: not an object');
  if (!m.grid || !Array.isArray(m.grid.tiles)) throw new Error('map: missing grid.tiles');
  const { width, height, tiles } = m.grid;
  if (typeof width !== 'number' || typeof height !== 'number') {
    throw new Error('map: grid width/height must be numbers');
  }
  if (tiles.length !== width * height) {
    throw new Error(`map: grid has ${tiles.length} tiles, expected ${width * height}`);
  }
  if (typeof m.id !== 'string' || typeof m.region !== 'string' || typeof m.palette !== 'string') {
    throw new Error('map: id/region/palette must be strings');
  }
  return m as GameMap;
}

const key = (x: number, y: number): string => `${x},${y}`;

export class World {
  readonly map: GameMap;
  private readonly doors = new Map<string, DoorState>();

  constructor(map: GameMap) {
    this.map = map;
    for (const d of map.doors ?? []) {
      this.doors.set(key(d.at[0], d.at[1]), {
        open: false,
        label: d.label,
        locked: d.locked ?? false,
      });
    }
  }

  get width(): number {
    return this.map.grid.width;
  }
  get height(): number {
    return this.map.grid.height;
  }

  /** Raw grid tile id; treats out-of-bounds as solid wall id 1. */
  tileAt(x: number, y: number): TileId {
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return 1;
    return this.map.grid.tiles[y * this.width + x] ?? 0;
  }

  /**
   * Solidity query for the raycaster/collision: 0 if passable, else the solid
   * tile id (wall id, or DOOR_TILE for a closed door).
   */
  solidAt = (x: number, y: number): number => {
    const door = this.doors.get(key(x, y));
    if (door) return door.open ? 0 : DOOR_TILE;
    return this.tileAt(x, y);
  };

  /** True if a circle-body cannot occupy tile (x,y). */
  isBlocked(x: number, y: number): boolean {
    return this.solidAt(Math.floor(x), Math.floor(y)) > 0;
  }

  /**
   * Try to open a door directly in front of `pos` facing `dir` (within ~1 tile).
   * Returns 'opened' | 'locked' | 'none' so callers can play the right SFX.
   * M0: `locked` doors still open (lock/evidence logic is an M1 concern) but we
   * surface the state so the hook is ready.
   */
  tryOpenDoor(pos: Vec2, dir: Vec2): 'opened' | 'locked' | 'none' {
    const tx = Math.floor(pos.x + dir.x * 0.8);
    const ty = Math.floor(pos.y + dir.y * 0.8);
    const door = this.doors.get(key(tx, ty));
    if (!door || door.open) return 'none';
    door.open = true;
    return door.locked ? 'locked' : 'opened';
  }
}

// Entities for M0 are static billboards (no AI — that's M1). This module turns
// the map's authored entities into renderable sprite instances, resolving each
// entity `type` to a procedural texture from the TextureSet.

import type { GameMap, Vec2 } from './types';
import type { TextureSet } from '../render/textures';
import type { SpriteInstance } from '../render/sprites';

export interface Entity {
  type: string;
  pos: Vec2;
}

export function createEntities(map: GameMap): Entity[] {
  return (map.entities ?? []).map((e) => ({
    type: e.type,
    // Center entities in their tile.
    pos: { x: e.at[0] + 0.5, y: e.at[1] + 0.5 },
  }));
}

/** Resolve entities to draw-ready sprite instances (texture per type). */
export function spriteInstances(entities: Entity[], tex: TextureSet): SpriteInstance[] {
  const fallback = tex.sprites.get('__default')!;
  return entities.map((e) => ({
    pos: e.pos,
    texture: tex.sprites.get(e.type) ?? fallback,
  }));
}

// Synthesized audio (docs/08) — no asset files. A tiny Web Audio synth produces
// retro SFX (footstep, door, pickup) and a low ambient drone. The AudioContext is
// created lazily on the first user gesture (pointer lock) to satisfy browser
// autoplay policy. Structured so docs/05's Trust-reactive mixing can hook in later.

export class Audio {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private droneGain: GainNode | null = null;

  /** Call from a user gesture. Idempotent. */
  resume(): void {
    if (this.ctx) {
      void this.ctx.resume();
      return;
    }
    const Ctor: typeof AudioContext =
      window.AudioContext ?? (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    const ctx = new Ctor();
    this.ctx = ctx;

    const master = ctx.createGain();
    master.gain.value = 0.5;
    master.connect(ctx.destination);
    this.master = master;

    this.startDrone();
  }

  /** Low ambient two-oscillator drone; a bed the Trust mix can detune later. */
  private startDrone(): void {
    if (!this.ctx || !this.master) return;
    const ctx = this.ctx;
    const gain = ctx.createGain();
    gain.gain.value = 0.06;
    gain.connect(this.master);
    this.droneGain = gain;

    for (const freq of [55, 82.4]) {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = freq;
      const lfo = ctx.createOscillator();
      lfo.type = 'sine';
      lfo.frequency.value = 0.12;
      const lfoGain = ctx.createGain();
      lfoGain.gain.value = 1.5;
      lfo.connect(lfoGain).connect(osc.frequency);
      osc.connect(gain);
      osc.start();
      lfo.start();
    }
  }

  /** Short percussive/tonal blip used by the SFX helpers. */
  private blip(
    type: OscillatorType,
    freq: number,
    dur: number,
    vol: number,
    sweepTo?: number,
  ): void {
    if (!this.ctx || !this.master) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, now);
    if (sweepTo !== undefined) osc.frequency.exponentialRampToValueAtTime(sweepTo, now + dur);
    gain.gain.setValueAtTime(vol, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    osc.connect(gain).connect(this.master);
    osc.start(now);
    osc.stop(now + dur);
  }

  footstep(): void {
    this.blip('square', 90, 0.06, 0.12, 60);
  }

  door(): void {
    this.blip('sawtooth', 140, 0.28, 0.16, 70);
  }

  pickup(): void {
    this.blip('triangle', 520, 0.12, 0.18, 880);
  }
}

// AgentMarvin — M0 entry point. Boots the canvas, loads the map, and runs the
// fixed-timestep loop: input → move (with collision) → raycast walls → sprites →
// HUD. See docs/11-technical-spec.md for the module architecture.

import { GameLoop } from './core/loop';
import { Input } from './core/input';
import { Framebuffer } from './render/framebuffer';
import { renderWalls } from './render/raycaster';
import { renderSprites } from './render/sprites';
import { buildTextures } from './render/textures';
import { drawDebug } from './render/hud';
import { parseMap, World } from './world/map';
import { createEntities, spriteInstances } from './world/entities';
import { Audio } from './audio/audio';
import type { Player, Vec2 } from './world/types';

const MOVE_SPEED = 3.2; // tiles / second
const BODY_RADIUS = 0.2;
const FOV = 0.66; // camera-plane half-length (~66° horizontal)

async function main(): Promise<void> {
  const canvas = document.getElementById('screen') as HTMLCanvasElement | null;
  const overlay = document.getElementById('overlay');
  if (!canvas) throw new Error('missing #screen canvas');

  const fb = new Framebuffer(canvas);
  Framebuffer.fitCanvas(canvas);
  window.addEventListener('resize', () => Framebuffer.fitCanvas(canvas));

  // Load level.
  const res = await fetch('/maps/working-directory.json');
  if (!res.ok) throw new Error(`failed to load map: ${res.status}`);
  const map = parseMap(await res.json());
  const world = new World(map);
  const tex = buildTextures(map.palette);
  const entities = createEntities(map);
  const sprites = spriteInstances(entities, tex);

  // Player from spawn.
  const angle = map.spawn?.angle ?? 0;
  const spawnAt = map.spawn?.at ?? [1.5, 1.5];
  const player: Player = {
    pos: { x: spawnAt[0] + 0.5, y: spawnAt[1] + 0.5 },
    dir: { x: Math.cos(angle), y: Math.sin(angle) },
    plane: { x: -Math.sin(angle) * FOV, y: Math.cos(angle) * FOV },
  };

  const audio = new Audio();
  const input = new Input(canvas);
  input.attach();
  input.onFirstLock = () => audio.resume();

  // Show/hide the click-to-start overlay with pointer lock.
  document.addEventListener('pointerlockchange', () => {
    if (!overlay) return;
    overlay.classList.toggle('hidden', input.isLocked);
  });

  const depth = new Float32Array(fb.width);
  let fps = 0;
  let footstepTimer = 0;

  function rotate(p: Player, a: number): void {
    const cos = Math.cos(a);
    const sin = Math.sin(a);
    const dx = p.dir.x;
    p.dir.x = dx * cos - p.dir.y * sin;
    p.dir.y = dx * sin + p.dir.y * cos;
    const px = p.plane.x;
    p.plane.x = px * cos - p.plane.y * sin;
    p.plane.y = px * sin + p.plane.y * cos;
  }

  function tryMove(pos: Vec2, dx: number, dy: number): boolean {
    let moved = false;
    const nx = pos.x + dx;
    if (!world.isBlocked(nx + Math.sign(dx) * BODY_RADIUS, pos.y)) {
      pos.x = nx;
      moved = moved || dx !== 0;
    }
    const ny = pos.y + dy;
    if (!world.isBlocked(pos.x, ny + Math.sign(dy) * BODY_RADIUS)) {
      pos.y = ny;
      moved = moved || dy !== 0;
    }
    return moved;
  }

  function update(dt: number): void {
    // Mouse look.
    const yaw = input.consumeMouseDx();
    if (yaw !== 0) rotate(player, yaw);

    // Movement relative to facing.
    let forward = 0;
    let strafe = 0;
    if (input.isDown('forward')) forward += 1;
    if (input.isDown('back')) forward -= 1;
    if (input.isDown('right')) strafe += 1;
    if (input.isDown('left')) strafe -= 1;

    let moved = false;
    if (forward !== 0 || strafe !== 0) {
      const len = Math.hypot(forward, strafe) || 1;
      const f = (forward / len) * MOVE_SPEED * dt;
      const s = (strafe / len) * MOVE_SPEED * dt;
      // strafe uses the camera plane direction (perpendicular to dir)
      const dx = player.dir.x * f + player.plane.x * s;
      const dy = player.dir.y * f + player.plane.y * s;
      moved = tryMove(player.pos, dx, dy);
    }

    // Footstep SFX while moving, throttled.
    footstepTimer -= dt;
    if (moved && footstepTimer <= 0) {
      audio.footstep();
      footstepTimer = 0.34;
    }

    // Door interaction.
    if (input.wasPressed('interact')) {
      const result = world.tryOpenDoor(player.pos, player.dir);
      if (result !== 'none') audio.door();
    }
  }

  function render(_alpha: number): void {
    renderWalls(fb, player, world.solidAt, tex, depth);
    renderSprites(fb, player, sprites, depth);
    drawDebug(fb, fps, player.pos.x, player.pos.y);
    fb.present();
  }

  const loop = new GameLoop({
    update,
    render,
    onFps: (v) => {
      fps = v;
    },
  });
  loop.start();
}

void main().catch((err) => {
  console.error(err);
  const overlay = document.getElementById('overlay');
  if (overlay) overlay.textContent = `boot error: ${String(err)}`;
});

import { describe, it, expect } from 'vitest';
import { Rng } from '../src/core/rng';

describe('Rng', () => {
  it('is deterministic for a given seed', () => {
    const a = new Rng(12345);
    const b = new Rng(12345);
    const seqA = Array.from({ length: 8 }, () => a.next());
    const seqB = Array.from({ length: 8 }, () => b.next());
    expect(seqA).toEqual(seqB);
  });

  it('produces different streams for different seeds', () => {
    const a = new Rng(1);
    const b = new Rng(2);
    expect(a.next()).not.toEqual(b.next());
  });

  it('next() stays in [0,1)', () => {
    const r = new Rng(999);
    for (let i = 0; i < 1000; i++) {
      const v = r.next();
      expect(v).toBeGreaterThanOrEqual(0);
      expect(v).toBeLessThan(1);
    }
  });

  it('int() respects inclusive bounds', () => {
    const r = new Rng(7);
    for (let i = 0; i < 1000; i++) {
      const v = r.int(3, 6);
      expect(v).toBeGreaterThanOrEqual(3);
      expect(v).toBeLessThanOrEqual(6);
      expect(Number.isInteger(v)).toBe(true);
    }
  });
});

