59	  const depth = new Float32Array(fb.width);
60	  let fps = 0;
61	  let footstepTimer = 0;
62	
63	  function rotate(p: Player, a: number): void {
64	    const cos = Math.cos(a);
65	    const sin = Math.sin(a);
66	    const dx = p.dir.x;
67	    p.dir.x = dx * cos - p.dir.y * sin;
