1	// Entities for M0 are static billboards (no AI — that's M1). This module turns
2	// the map's authored entities into renderable sprite instances, resolving each
3	// entity `type` to a procedural texture from the TextureSet.
4	
5	import type { GameMap, Vec2 } from './types';
6	import type { TextureSet } from '../render/textures';
7	import type { SpriteInstance } from '../render/sprites';
8	
9	export interface Entity {
10	  type: string;
11	  pos: Vec2;
12	}
13	
14	export function createEntities(map: GameMap): Entity[] {
15	  return (map.entities ?? []).map((e) => ({
16	    type: e.type,
17	    // Center entities in their tile.
18	    pos: { x: e.at[0] + 0.5, y: e.at[1] + 0.5 },
19	  }));
20	}
21	
22	/** Resolve entities to draw-ready sprite instances (texture per type). */
23	export function spriteInstances(entities: Entity[], tex: TextureSet): SpriteInstance[] {
24	  const fallback = tex.sprites.get('__default')!;
25	  return entities.map((e) => ({
26	    pos: e.pos,
27	    texture: tex.sprites.get(e.type) ?? fallback,
28	  }));
29	}
