/** One recorded event in a Session log (docs/02 §1; replayed through the sim). */
export type SessionEvent =
  | { t: number; kind: 'move'; x: number; y: number; dirX: number; dirY: number }
  | { t: number; kind: 'door'; at: [number, number] }
