// Trust — the health replacement (docs/05). A 0-100 pool whose tier drives world
// distortion. M1 ships T0/T1 only; the low end is clamped so the slice teaches
// without a hard-fail state (full tiers + Checkpoint recovery are M2).

export type TrustTier = 'T0' | 'T1' | 'below';

export interface TrustChange {
  value: number;
  tier: TrustTier;
  /** True if this change moved between tiers. */
  crossedTier: boolean;
  delta: number;
  reason?: string;
}

/** Tier for a given trust value (docs/05: T0 >=75, T1 50-74, below <50). */
export function tierFor(value: number): TrustTier {
  if (value >= 75) return 'T0';
  if (value >= 50) return 'T1';
  return 'below';
}

export class Trust {
  value: number;
  /** Slice clamp: Trust can't drop below this (keeps us in T0/T1). */
  readonly floor: number;

  constructor(start = 100, floor = 50) {
    this.floor = floor;
    this.value = Math.max(floor, Math.min(100, start));
  }

  get tier(): TrustTier {
    return tierFor(this.value);
  }

  /** Apply a delta (clamped). Returns the resulting state + whether a tier changed. */
  change(delta: number, reason?: string): TrustChange {
    const before = this.tier;
    this.value = Math.max(this.floor, Math.min(100, this.value + delta));
    const tier = this.tier;
    return { value: this.value, tier, crossedTier: tier !== before, delta, reason };
  }
}

// Evidence tokens (docs/02) — gathered from Sessions/Scanner and docked at a Gate.
// Tokens are keyed by source so the same discovery can't be double-counted.

export class Evidence {
  private sources = new Set<string>();

  /** Record a piece of evidence from `source`. Returns true if it was new. */
  add(source: string): boolean {
    if (this.sources.has(source)) return false;
    this.sources.add(source);
    return true;
  }

  get count(): number {
    return this.sources.size;
  }

  has(n: number): boolean {
    return this.sources.size >= n;
  }

  /** Consume `n` tokens (e.g. docked at a Gate). Returns false if insufficient. */
  spend(n: number): boolean {
    if (this.sources.size < n) return false;
    const it = this.sources.values();
    for (let i = 0; i < n; i++) {
      const next = it.next();
      if (!next.done) this.sources.delete(next.value);
    }
    return true;
  }

  list(): string[] {
    return [...this.sources];
  }
}

// Sessions (docs/02 §1) — replay a recorded action log as a translucent ghost that
// re-performs history. `poseAt` / `discreteEventsBetween` are pure (unit-tested);
// the Ghost class wraps them with a clock and fires door/say callbacks.

import type { MapSession, SessionEvent, Vec2 } from '../world/types';

export interface Pose {
  x: number;
  y: number;
  dirX: number;
  dirY: number;
}

/** Move keyframes only, in time order. */
function moveKeys(log: MapSession): Extract<SessionEvent, { kind: 'move' }>[] {
  return log.actions.filter((e): e is Extract<SessionEvent, { kind: 'move' }> => e.kind === 'move');
}

/** Total duration = timestamp of the last event (0 if none). */
export function duration(log: MapSession): number {
  return log.actions.reduce((m, e) => Math.max(m, e.t), 0);
}

/** Interpolated pose at time `t` (pure). Clamps to the first/last keyframe. */
export function poseAt(log: MapSession, t: number): Pose {
  const keys = moveKeys(log);
  if (keys.length === 0) return { x: 0, y: 0, dirX: 1, dirY: 0 };
  if (t <= keys[0]!.t) return poseOf(keys[0]!);
  const last = keys[keys.length - 1]!;
  if (t >= last.t) return poseOf(last);
  for (let i = 0; i < keys.length - 1; i++) {
    const a = keys[i]!;
    const b = keys[i + 1]!;
    if (t >= a.t && t <= b.t) {
      const span = b.t - a.t || 1;
      const k = (t - a.t) / span;
      return {
        x: lerp(a.x, b.x, k),
        y: lerp(a.y, b.y, k),
        dirX: lerp(a.dirX, b.dirX, k),
        dirY: lerp(a.dirY, b.dirY, k),
      };
    }
  }
  return poseOf(last);
}

/** Non-move events whose timestamp falls in (t0, t1] (pure). */
export function discreteEventsBetween(
  log: MapSession,
  t0: number,
  t1: number,
): Exclude<SessionEvent, { kind: 'move' }>[] {
  return log.actions.filter(
    (e): e is Exclude<SessionEvent, { kind: 'move' }> =>
      e.kind !== 'move' && e.t > t0 && e.t <= t1,
  );
}

function poseOf(k: Extract<SessionEvent, { kind: 'move' }>): Pose {
  return { x: k.x, y: k.y, dirX: k.dirX, dirY: k.dirY };
}
function lerp(a: number, b: number, k: number): number {
  return a + (b - a) * k;
}

export interface GhostCallbacks {
  onDoor(at: [number, number]): void;
  onSay(text: string): void;
  onDone(log: MapSession): void;
}

/** A live replay of a Session. Read-only in the world; harmless to the player. */
export class Ghost {
  readonly pos: Vec2 = { x: 0, y: 0 };
  readonly dir: Vec2 = { x: 1, y: 0 };
  done = false;
  private elapsed = 0;
  private readonly total: number;

  constructor(
    readonly log: MapSession,
    private readonly cb: GhostCallbacks,
  ) {
    this.total = duration(log);
    const p = poseAt(log, 0);
    this.pos.x = p.x;
    this.pos.y = p.y;
    this.dir.x = p.dirX;
    this.dir.y = p.dirY;
  }

  /** Advance the ghost; fires door/say events crossed this step. */
  update(dt: number): void {
    if (this.done) return;
    const prev = this.elapsed;
    this.elapsed = Math.min(this.total, this.elapsed + dt);

    for (const e of discreteEventsBetween(this.log, prev, this.elapsed)) {
      if (e.kind === 'door') this.cb.onDoor(e.at);
      else if (e.kind === 'say') this.cb.onSay(e.text);
    }

    const p = poseAt(this.log, this.elapsed);
    this.pos.x = p.x;
    this.pos.y = p.y;
    this.dir.x = p.dirX;
    this.dir.y = p.dirY;

    if (this.elapsed >= this.total) {
      this.done = true;
      this.cb.onDone(this.log);
    }
  }

  /** 0..1 replay progress. */
  progress(): number {
    return this.total === 0 ? 1 : this.elapsed / this.total;
  }
}

// Session recorder (dev tool, docs/11) — the authentic way to author ghosts.
// Enable with ?record in the URL; it captures the player's pose at a fixed rate
// plus door/say events into a MapSession, then exports JSON to paste into a map's
// `sessions[]`. The sampling core is pure so it can be round-trip tested.

import type { MapSession, Player, SessionEvent } from '../world/types';

const SAMPLE_HZ = 10; // pose keyframes per second

export class Recorder {
  active = false;
  private id = 'recorded';
  private actions: SessionEvent[] = [];
  private clock = 0;
  private sinceSample = 0;

  /** Is recording available this session? (gated by ?record) */
  static isEnabled(): boolean {
    return typeof location !== 'undefined' && new URLSearchParams(location.search).has('record');
  }

  start(id = 'recorded'): void {
    this.id = id;
    this.actions = [];
    this.clock = 0;
    this.sinceSample = 1 / SAMPLE_HZ; // sample immediately
    this.active = true;
  }

  /** Call each sim tick with the current player pose. */
  sample(dt: number, player: Player): void {
    if (!this.active) return;
    this.clock += dt;
    this.sinceSample += dt;
    if (this.sinceSample >= 1 / SAMPLE_HZ) {
      this.sinceSample = 0;
      this.actions.push({
        t: round(this.clock),
        kind: 'move',
        x: round(player.pos.x),
        y: round(player.pos.y),
        dirX: round(player.dir.x),
        dirY: round(player.dir.y),
      });
    }
  }

  /** Record a discrete door event at the current time. */
  door(at: [number, number]): void {
    if (this.active) this.actions.push({ t: round(this.clock), kind: 'door', at });
  }

  /** Record a narration line at the current time. */
  say(text: string): void {
    if (this.active) this.actions.push({ t: round(this.clock), kind: 'say', text });
  }

  stop(): MapSession {
    this.active = false;
    return { id: this.id, actions: this.actions };
  }

  toJSON(): string {
    return JSON.stringify({ id: this.id, actions: this.actions }, null, 2);
  }

  /** Trigger a browser download of the recorded log (no-op outside the browser). */
  download(): void {
    if (typeof document === 'undefined') return;
    const blob = new Blob([this.toJSON()], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${this.id}.session.json`;
    a.click();
    URL.revokeObjectURL(url);
  }
}

function round(n: number): number {
  return Math.round(n * 1000) / 1000;
}

// Gates (docs/02 §5) — the ultimate mechanic. The training Gate always opens
// (M1), but the *decision* and the evidence behind it move Trust, which is the
// lesson. `evaluateGate` is pure so the outcomes are unit-tested.

import type { GateDecision } from '../world/types';

export interface GateOutcome {
  decision: GateDecision;
  /** The training Gate always opens; the decision is what carries weight. */
  opened: boolean;
  /** Promote with zero evidence — the anti-pattern the whole game warns about. */
  yolo: boolean;
  /** Sound call, backed by enough evidence. */
  correct: boolean;
  trustDelta: number;
  message: string;
}

export function evaluateGate(
  decision: GateDecision,
  evidenceCount: number,
  requiredEvidence: number,
  soundDecision: GateDecision,
): GateOutcome {
  const base = { decision, opened: true };

  if (decision === 'promote' && evidenceCount === 0) {
    return {
      ...base,
      yolo: true,
      correct: false,
      trustDelta: -30,
      message: 'YOLO MERGE: shipped to production with zero evidence. Trust collapses.',
    };
  }

  if (decision === soundDecision && evidenceCount >= requiredEvidence) {
    return {
      ...base,
      yolo: false,
      correct: true,
      trustDelta: +25,
      message: 'Evidence-backed decision. This is how you ship. Trust restored.',
    };
  }

  if (evidenceCount < requiredEvidence) {
    return {
      ...base,
      yolo: false,
      correct: false,
      trustDelta: -10,
      message: 'Not enough evidence to be sure of that call.',
    };
  }

  return {
    ...base,
    yolo: false,
    correct: false,
    trustDelta: -5,
    message: 'The evidence did not support that decision.',
  };
}

// Entities carry per-type runtime state (M1). This module owns the Entity shape,
// builds them from the map, and resolves each to a draw-ready sprite instance with
// state-driven alpha/tint (fading dispelled bots, exposed real/fake tints).

import type { GameMap, GateDecision, Vec2 } from './types';
import type { TextureSet } from '../render/textures';
import type { SpriteInstance } from '../render/sprites';
import { rgba } from '../render/framebuffer';

export interface Entity {
  type: string;
  pos: Vec2;
  /** Present/alive in the world; false once dispelled (bot) or taken (pickup). */
  alive: boolean;
  /** Dispel/spawn animation, 1 = fully present, 0 = gone. */
  fade: number;
  // hallucination-bot
  real?: boolean;
  exposed?: boolean;
  // session-anchor
  sessionId?: string;
  replayed?: boolean;
  // pickup
  item?: string;
  // gate-node
  requiresEvidence?: number;
  soundDecision?: GateDecision;
  // rubber-duck / readme
  hint?: string;
  used?: boolean;
}

export function createEntities(map: GameMap): Entity[] {
  return (map.entities ?? []).map((e) => ({
    type: e.type,
    pos: { x: e.at[0] + 0.5, y: e.at[1] + 0.5 },
    alive: true,
    fade: 1,
    real: e.real,
    exposed: false,
    sessionId: e.sessionId,
    replayed: false,
    item: e.item,
    requiresEvidence: e.requiresEvidence,
    soundDecision: e.soundDecision,
    hint: e.hint,
    used: false,
  }));
}

/** Tint applied to a scanned/exposed bot: green if real, red if hallucinated. */
function exposedTint(real: boolean | undefined): number {
  return real ? rgba(120, 255, 150) : rgba(255, 90, 110);
}

/** Build sprite instances for the currently-visible entities. */
export function entitySprites(entities: Entity[], tex: TextureSet, time: number): SpriteInstance[] {
  const fallback = tex.sprites.get('__default')!;
  const out: SpriteInstance[] = [];
  for (const e of entities) {
    if (!e.alive && e.fade <= 0) continue;
    const inst: SpriteInstance = {
      pos: e.pos,
      texture: tex.sprites.get(e.type) ?? fallback,
    };
    if (e.fade < 1) inst.alpha = e.fade;
    if (e.type === 'hallucination-bot' && e.exposed) {
      inst.tint = exposedTint(e.real);
      // Fakes flicker while dissolving.
      if (!e.real) inst.alpha = (inst.alpha ?? 1) * (0.55 + 0.45 * Math.sin(time * 18));
    }
    out.push(inst);
  }
  return out;
}

