// Weapon system (docs/03). Marvin's arsenal is a detective's toolkit — the M1
// weapons (Context Scanner, Session Replayer) gather truth, they don't deal
// damage (Trust over Violence). This module owns ownership/selection and the
// shared WeaponContext + target-picking the individual weapons act through.

import type { Entity } from '../world/entities';
import type { MapSession, Player, WeaponId } from '../world/types';
import type { World } from '../world/map';
import type { Trust } from '../mechanics/trust';
import type { Evidence } from '../mechanics/evidence';
import type { Audio } from '../audio/audio';

/** The slice of game state a weapon needs to act. Passed in by game.ts. */
export interface WeaponContext {
  player: Player;
  entities: Entity[];
  world: World;
  trust: Trust;
  evidence: Evidence;
  sessions: MapSession[];
  audio: Audio;
  spawnGhost(session: MapSession): void;
  narrate(text: string): void;
}

export const WEAPON_NAMES: Record<WeaponId, string> = {
  'context-scanner': 'Context Scanner',
  'session-replayer': 'Session Replayer',
};

const SLOTS: Record<number, WeaponId> = {
  1: 'context-scanner',
  2: 'session-replayer',
};

export class WeaponSystem {
  private owned = new Set<WeaponId>(['context-scanner']);
  current: WeaponId = 'context-scanner';

  has(id: WeaponId): boolean {
    return this.owned.has(id);
  }

  give(id: WeaponId): boolean {
    if (this.owned.has(id)) return false;
    this.owned.add(id);
    this.current = id; // auto-equip on pickup
    return true;
  }

  /** Select by number key (1/2). Ignores unowned slots. */
  selectSlot(n: number): void {
    const id = SLOTS[n];
    if (id && this.owned.has(id)) this.current = id;
  }

  name(): string {
    return WEAPON_NAMES[this.current];
  }
}

/** A unique key for evidence/dedup, from an entity's tile position. */
export function entityKey(e: Entity): string {
  return `${Math.floor(e.pos.x)},${Math.floor(e.pos.y)}`;
}

/**
 * Nearest alive entity of `types` within `range` and inside the forward cone
 * (dot(dir, toEntity) >= cosTol). Returns null if none.
 */
export function pickTarget(
  ctx: WeaponContext,
  types: string[],
  range: number,
  cosTol: number,
): Entity | null {
  const { player } = ctx;
  let best: Entity | null = null;
  let bestDist = Infinity;
  for (const e of ctx.entities) {
    if (!e.alive || !types.includes(e.type)) continue;
    const dx = e.pos.x - player.pos.x;
    const dy = e.pos.y - player.pos.y;
    const dist = Math.hypot(dx, dy);
    if (dist > range || dist < 1e-4) continue;
    const dot = (dx / dist) * player.dir.x + (dy / dist) * player.dir.y;
    if (dot < cosTol) continue;
    if (dist < bestDist) {
      bestDist = dist;
      best = e;
    }
  }
  return best;
}

// Context Scanner (docs/03 slot 1) — reveals the world and, crucially, exposes
// which Hallucination Bots are real vs. fake (docs/04). Exposing beats attacking:
// dispelling a fake costs nothing and yields evidence; acting on a hallucination
// (never verifying) is what costs Trust, handled where the player acts.

import type { Entity } from '../world/entities';
import { pickTarget, entityKey, type WeaponContext } from './weapons';

const CONE_RANGE = 4.0;
const CONE_COS = Math.cos((35 * Math.PI) / 180); // wide cone
const PING_RANGE = 7.0;
const PING_COS = Math.cos((10 * Math.PI) / 180); // narrow, precise

/** Reveal a single bot's nature; dispel it if it's a hallucination. */
function expose(ctx: WeaponContext, bot: Entity): boolean {
  if (bot.exposed) return false;
  bot.exposed = true;
  if (bot.real) {
    ctx.narrate('Scanner: REAL agent. This one actually touched the repo.');
    return false;
  }
  // Fake → begin dissolving; verifying it is the "right" action.
  bot.alive = false; // game loop fades it out
  const fresh = ctx.evidence.add(`expose:${entityKey(bot)}`);
  ctx.trust.change(+3, 'exposed a hallucination');
  ctx.narrate('Scanner: HALLUCINATION dispelled. Verify before you act.');
  return fresh;
}

/** Primary: wide cone that exposes every bot in front, at short range. */
export function scannerPrimary(ctx: WeaponContext): void {
  ctx.audio.scan();
  let any = false;
  for (const e of ctx.entities) {
    if (!e.alive || e.type !== 'hallucination-bot' || e.exposed) continue;
    const dx = e.pos.x - ctx.player.pos.x;
    const dy = e.pos.y - ctx.player.pos.y;
    const dist = Math.hypot(dx, dy);
    if (dist > CONE_RANGE || dist < 1e-4) continue;
    const dot = (dx / dist) * ctx.player.dir.x + (dy / dist) * ctx.player.dir.y;
    if (dot < CONE_COS) continue;
    expose(ctx, e);
    any = true;
  }
  if (!any) ctx.narrate('Scanner sweep: nothing to verify here.');
}

/** Alt-fire: precise long-range ping on the single bot under the crosshair. */
export function scannerAlt(ctx: WeaponContext): void {
  ctx.audio.ping();
  const bot = pickTarget(ctx, ['hallucination-bot'], PING_RANGE, PING_COS);
  if (!bot) {
    ctx.narrate('Ping: no target in the crosshair.');
    return;
  }
  if (bot.exposed) {
    ctx.narrate('Already verified.');
    return;
  }
  expose(ctx, bot);
}

// Session Replayer (docs/03 slot 2) — fire at a Session Anchor to replay history
// as a ghost (docs/02 §1). The ghost opens the door it once opened and reveals the
// true path; evidence is awarded when the replay completes (handled by game.ts via
// the ghost's onDone callback).

import { pickTarget, type WeaponContext } from './weapons';

const ANCHOR_RANGE = 5.0;
const ANCHOR_COS = Math.cos((30 * Math.PI) / 180);

/** Primary: replay the Session Anchor under the crosshair. */
export function replayerPrimary(ctx: WeaponContext): void {
  const anchor = pickTarget(ctx, ['session-anchor'], ANCHOR_RANGE, ANCHOR_COS);
  if (!anchor) {
    ctx.narrate('Session Replayer: aim at a Session Anchor.');
    return;
  }
  if (anchor.replayed) {
    ctx.narrate('That session has already been replayed.');
    return;
  }
  const session = ctx.sessions.find((s) => s.id === anchor.sessionId);
  if (!session) {
    ctx.narrate('Session data is missing for that anchor.');
    return;
  }
  anchor.replayed = true;
  ctx.audio.ghost();
  ctx.narrate('Replaying session — watch what history actually did.');
  ctx.spawnGhost(session);
}

/** Alt-fire (stretch): scrub. No-op for M1. */
export function replayerAlt(ctx: WeaponContext): void {
  ctx.narrate('Scrub is not available yet.');
}

