// Game orchestration (M1). Owns the mutable GameState and the per-tick update +
// render. main.ts bootstraps this; the individual systems (trust, evidence,
// sessions, gates, weapons) live in mechanics/ and weapons/ and are driven here.

import type { GameMap, Player, Vec2, WeaponId } from '../world/types';
import { World } from '../world/map';
import { createEntities, entitySprites, type Entity } from '../world/entities';
import { buildTextures, type TextureSet } from '../render/textures';
import { renderWalls } from '../render/raycaster';
import { renderSprites, type SpriteInstance } from '../render/sprites';
import { applyDistortion } from '../render/distortion';
import type { Framebuffer } from '../render/framebuffer';
import type { Hud } from '../render/hud';
import type { GateUI } from '../render/gateui';
import { Trust } from '../mechanics/trust';
import { Evidence } from '../mechanics/evidence';
import { Ghost } from '../mechanics/sessions';
import { Recorder } from '../mechanics/recorder';
import { evaluateGate, type GateOutcome } from '../mechanics/gates';
import { WeaponSystem, WEAPON_NAMES, type WeaponContext } from '../weapons/weapons';
import { scannerPrimary, scannerAlt } from '../weapons/contextScanner';
import { replayerPrimary, replayerAlt } from '../weapons/sessionReplayer';
import type { Input } from './input';
import type { Audio } from '../audio/audio';
import { REVEAL_LINES } from '../campaign/episode1';

const MOVE_SPEED = 3.2;
const BODY_RADIUS = 0.2;
const FOV = 0.66;
const PICKUP_RANGE = 0.6;
const INTERACT_RANGE = 1.8;
const INTERACT_COS = Math.cos((55 * Math.PI) / 180);

export interface GameDeps {
  map: GameMap;
  audio: Audio;
  hud: Hud;
  gateui: GateUI;
}

export interface GameState {
  map: GameMap;
  world: World;
  player: Player;
  tex: TextureSet;
  entities: Entity[];
  trust: Trust;
  evidence: Evidence;
  weapons: WeaponSystem;
  ghosts: Ghost[];
  recorder: Recorder;
  audio: Audio;
  hud: Hud;
  gateui: GateUI;
  time: number;
  footstepTimer: number;
  won: boolean;
}

export function createGame(deps: GameDeps): GameState {
  const { map, audio, hud, gateui } = deps;
  const world = new World(map);
  const tex = buildTextures(map.palette);
  const angle = map.spawn?.angle ?? 0;
  const at = map.spawn?.at ?? [1.5, 1.5];
  const player: Player = {
    pos: { x: at[0] + 0.5, y: at[1] + 0.5 },
    dir: { x: Math.cos(angle), y: Math.sin(angle) },
    plane: { x: -Math.sin(angle) * FOV, y: Math.cos(angle) * FOV },
  };

  const game: GameState = {
    map,
    world,
    player,
    tex,
    entities: createEntities(map),
    trust: new Trust(map.trustStart ?? 100),
    evidence: new Evidence(),
    weapons: new WeaponSystem(),
    ghosts: [],
    recorder: new Recorder(),
    audio,
    hud,
    gateui,
    time: 0,
    footstepTimer: 0,
    won: false,
  };

  hud.setWeapon(game.weapons.name());
  syncHud(game);
  return game;
}

// --- per-tick update ---------------------------------------------------------

export function updateGame(game: GameState, input: Input, dt: number): void {
  game.time += dt;
  if (game.recorder.active) game.recorder.sample(dt, game.player);

  // Frozen while the Gate console is open or the slice is won.
  if (game.gateui.isOpen || game.won) return;

  // Look.
  const yaw = input.consumeMouseDx();
  if (yaw !== 0) rotate(game.player, yaw);

  // Move.
  let forward = 0;
  let strafe = 0;
  if (input.isDown('forward')) forward += 1;
  if (input.isDown('back')) forward -= 1;
  if (input.isDown('right')) strafe += 1;
  if (input.isDown('left')) strafe -= 1;
  let moved = false;
  if (forward !== 0 || strafe !== 0) {
    const len = Math.hypot(forward, strafe) || 1;
    const f = (forward / len) * MOVE_SPEED * dt;
    const s = (strafe / len) * MOVE_SPEED * dt;
    const dx = game.player.dir.x * f + game.player.plane.x * s;
    const dy = game.player.dir.y * f + game.player.plane.y * s;
    moved = tryMove(game, dx, dy);
  }
  game.footstepTimer -= dt;
  if (moved && game.footstepTimer <= 0) {
    game.audio.footstep();
    game.footstepTimer = 0.34;
  }

  // Weapon select.
  if (input.wasPressed('weapon1')) game.weapons.selectSlot(1);
  if (input.wasPressed('weapon2')) game.weapons.selectSlot(2);
  game.hud.setWeapon(game.weapons.name());

  // Dev recorder toggle.
  if (input.wasPressed('record')) toggleRecord(game);

  // Fire.
  if (input.wasPressed('fire')) fireWeapon(game, 'primary');
  if (input.wasPressed('altfire')) fireWeapon(game, 'alt');

  // Interact.
  if (input.wasPressed('interact')) interact(game);

  // Ghosts.
  for (const g of game.ghosts) g.update(dt);
  game.ghosts = game.ghosts.filter((g) => !g.done);

  collectPickups(game);
  updateFades(game, dt);
  syncDistortion(game);
  syncHud(game);
}

// --- render ------------------------------------------------------------------

export function renderGame(game: GameState, fb: Framebuffer, depth: Float32Array): void {
  renderWalls(fb, game.player, game.world.solidAt, game.tex, depth);
  const sprites: SpriteInstance[] = entitySprites(game.entities, game.tex, game.time);
  const ghostTex = game.tex.sprites.get('ghost')!;
  for (const g of game.ghosts) {
    sprites.push({ pos: { x: g.pos.x, y: g.pos.y }, texture: ghostTex, alpha: 0.55 });
  }
  renderSprites(fb, game.player, sprites, depth);
  applyDistortion(fb, game.trust.tier, game.time);
}

// --- systems -----------------------------------------------------------------

function makeCtx(game: GameState): WeaponContext {
  return {
    player: game.player,
    entities: game.entities,
    world: game.world,
    trust: game.trust,
    evidence: game.evidence,
    sessions: game.map.sessions ?? [],
    audio: game.audio,
    spawnGhost: (s) => spawnGhost(game, s),
    narrate: (t) => narrate(game, t),
  };
}

function fireWeapon(game: GameState, mode: 'primary' | 'alt'): void {
  const ctx = makeCtx(game);
  switch (game.weapons.current) {
    case 'context-scanner':
      mode === 'primary' ? scannerPrimary(ctx) : scannerAlt(ctx);
      break;
    case 'session-replayer':
      mode === 'primary' ? replayerPrimary(ctx) : replayerAlt(ctx);
      break;
  }
}

function spawnGhost(game: GameState, session: GameState['map']['sessions'] extends undefined ? never : import('../world/types').MapSession): void {
  const ghost = new Ghost(session, {
    onDoor: (at) => {
      if (game.world.openDoorAt(at[0], at[1])) {
        game.audio.door();
        narrate(game, "GHOST opened the real door — history doesn't hallucinate.");
      }
    },
    onSay: (text) => narrate(game, `GHOST: ${text}`),
    onDone: (log) => {
      if (game.evidence.add(`session:${log.id}`)) {
        game.audio.evidence();
        game.trust.change(+2, 'session replayed');
        narrate(game, 'Evidence secured from the replay.');
      }
    },
  });
  game.ghosts.push(ghost);
}

function interact(game: GameState): void {
  const { player, world } = game;
  const tx = Math.floor(player.pos.x + player.dir.x * 0.8);
  const ty = Math.floor(player.pos.y + player.dir.y * 0.8);
  const label = world.doorLabelInFront(player.pos, player.dir);
  const r = world.tryOpenDoor(player.pos, player.dir);
  if (r === 'opened') {
    game.audio.door();
    if (game.recorder.active) game.recorder.door([tx, ty]);
    narrate(game, label ? `Opened ${label}` : 'Door opened.');
    return;
  }
  if (r === 'false') {
    game.trust.change(-2, 'false door');
    game.audio.door();
    narrate(game, 'That door was never real.');
    return;
  }
  if (r === 'locked') {
    narrate(game, 'Locked. Find another way — or replay a session.');
    return;
  }

  const e = pickInteractable(game);
  if (!e) return;
  if (e.type === 'rubber-duck') {
    e.used = true;
    narrate(game, e.hint ?? 'The duck stares back. Have you tried replaying a session?');
  } else if (e.type === 'readme') {
    if (!e.used) {
      game.trust.change(+2, 'read the readme');
      e.used = true;
    }
    narrate(game, `README: ${e.hint ?? 'the answer was in the docs all along.'}`);
  } else if (e.type === 'gate-node') {
    openGate(game, e);
  }
}

function openGate(game: GameState, node: Entity): void {
  const required = node.requiresEvidence ?? 1;
  const sound = node.soundDecision ?? 'reject';
  // Release the pointer so the console buttons are clickable.
  if (typeof document !== 'undefined') document.exitPointerLock();
  game.gateui.show(game.evidence.count, required, (decision) => {
    const outcome = evaluateGate(decision, game.evidence.count, required, sound);
    game.trust.change(outcome.trustDelta, 'gate decision');
    game.audio.gate();
    game.gateui.hide();
    endSlice(game, outcome);
  });
}

function endSlice(game: GameState, outcome: GateOutcome): void {
  game.won = true;
  syncHud(game);
  const verdict = outcome.correct
    ? 'You restored trust the right way.'
    : outcome.yolo
      ? 'You shipped without evidence. Classic YOLO merge.'
      : 'The call was made — and Trust took the hit.';
  game.hud.showReveal(outcome.correct ? 'SESSION ARCHIVE STABILIZED' : 'GATE CLOSED', [
    outcome.message,
    '',
    ...REVEAL_LINES,
    '',
    verdict,
  ]);
}

function collectPickups(game: GameState): void {
  for (const e of game.entities) {
    if (!e.alive || e.type !== 'pickup') continue;
    const dx = e.pos.x - game.player.pos.x;
    const dy = e.pos.y - game.player.pos.y;
    if (Math.hypot(dx, dy) > PICKUP_RANGE) continue;
    const wid = e.item as WeaponId | undefined;
    e.alive = false;
    if (wid && game.weapons.give(wid)) {
      game.audio.pickup();
      game.hud.setWeapon(game.weapons.name());
      narrate(game, `Acquired ${WEAPON_NAMES[wid]}. It's equipped — fire it.`);
    }
  }
}

function pickInteractable(game: GameState): Entity | null {
  const { player } = game;
  let best: Entity | null = null;
  let bestDist = Infinity;
  for (const e of game.entities) {
    if (!e.alive) continue;
    if (e.type !== 'rubber-duck' && e.type !== 'readme' && e.type !== 'gate-node') continue;
    const dx = e.pos.x - player.pos.x;
    const dy = e.pos.y - player.pos.y;
    const dist = Math.hypot(dx, dy);
    if (dist > INTERACT_RANGE || dist < 1e-4) continue;
    const dot = (dx / dist) * player.dir.x + (dy / dist) * player.dir.y;
    if (dot < INTERACT_COS) continue;
    if (dist < bestDist) {
      bestDist = dist;
      best = e;
    }
  }
  return best;
}

function updateFades(game: GameState, dt: number): void {
  for (const e of game.entities) {
    if (!e.alive && e.fade > 0) e.fade = Math.max(0, e.fade - dt * 3);
  }
}

function syncDistortion(game: GameState): void {
  const distorted = game.trust.tier !== 'T0';
  game.world.distortionActive = distorted;
  game.hud.setGlitch(distorted);
}

function syncHud(game: GameState): void {
  game.hud.setTrust(game.trust.value, game.trust.tier);
  game.hud.setEvidence(game.evidence.count);
}

function toggleRecord(game: GameState): void {
  if (!Recorder.isEnabled()) return;
  if (game.recorder.active) {
    game.recorder.stop();
    game.recorder.download();
    narrate(game, 'Recording saved to a .session.json download.');
  } else {
    game.recorder.start('recorded');
    narrate(game, 'Recording session — move, then press ` again to save.');
  }
}

function narrate(game: GameState, text: string): void {
  game.hud.toast(text);
}

// --- movement helpers --------------------------------------------------------

function rotate(p: Player, a: number): void {
  const cos = Math.cos(a);
  const sin = Math.sin(a);
  const dx = p.dir.x;
  p.dir.x = dx * cos - p.dir.y * sin;
  p.dir.y = dx * sin + p.dir.y * cos;
  const px = p.plane.x;
  p.plane.x = px * cos - p.plane.y * sin;
  p.plane.y = px * sin + p.plane.y * cos;
}

function tryMove(game: GameState, dx: number, dy: number): boolean {
  const pos: Vec2 = game.player.pos;
  let moved = false;
  const nx = pos.x + dx;
  if (!game.world.isBlocked(nx + Math.sign(dx) * BODY_RADIUS, pos.y)) {
    pos.x = nx;
    moved = moved || dx !== 0;
  }
  const ny = pos.y + dy;
  if (!game.world.isBlocked(pos.x, ny + Math.sign(dy) * BODY_RADIUS)) {
    pos.y = ny;
    moved = moved || dy !== 0;
  }
  return moved;
}

// AgentMarvin — entry point. Boots the canvas + DOM HUD, loads Episode 1, and
// runs the fixed-timestep loop delegating to core/game.ts. See docs/11 for the
// module architecture and docs/06 for the episode.

import { GameLoop } from './core/loop';
import { Input } from './core/input';
import { Framebuffer } from './render/framebuffer';
import { Hud } from './render/hud';
import { GateUI } from './render/gateui';
import { parseMap } from './world/map';
import { createGame, updateGame, renderGame } from './core/game';
import { Audio } from './audio/audio';

const MAP_URL = '/maps/episode1-lost-sessions.json';

async function main(): Promise<void> {
  const canvas = document.getElementById('screen') as HTMLCanvasElement | null;
  const overlay = document.getElementById('overlay');
  if (!canvas) throw new Error('missing #screen canvas');

  const fb = new Framebuffer(canvas);
  Framebuffer.fitCanvas(canvas);
  window.addEventListener('resize', () => Framebuffer.fitCanvas(canvas));

  const res = await fetch(MAP_URL);
  if (!res.ok) throw new Error(`failed to load map: ${res.status}`);
  const map = parseMap(await res.json());

  const audio = new Audio();
  const hud = new Hud();
  const gateui = new GateUI();
  const game = createGame({ map, audio, hud, gateui });

  const input = new Input(canvas);
  input.attach();
  input.onFirstLock = () => audio.resume();

  document.addEventListener('pointerlockchange', () => {
    if (overlay) overlay.classList.toggle('hidden', input.isLocked);
  });

  const depth = new Float32Array(fb.width);

  const loop = new GameLoop({
    update: (dt) => updateGame(game, input, dt),
    render: () => {
      renderGame(game, fb, depth);
      fb.present();
    },
  });
  loop.start();
}

void main().catch((err) => {
  console.error(err);
  const overlay = document.getElementById('overlay');
  if (overlay) overlay.textContent = `boot error: ${String(err)}`;
});

// Episode 1 — "Lost Sessions" (docs/06). M1 runs the whole episode as one
// connected map, so the campaign layer is light: it holds the end-of-slice reveal
// text that maps the fiction to real Entire (docs/07). Level geometry + ghost logs
// live in public/maps/episode1-lost-sessions.json.

/** The final-reveal mapping shown when the Gate closes (docs/07). */
export const REVEAL_LINES: string[] = [
  'Session Replayer   →   Sessions',
  'Context Scanner    →   Context',
  'Evidence + Gate    →   production decisions',
  '',
  'You were learning Entire the whole time.',
];

// Generates public/maps/episode1-lost-sessions.json (docs/06 Episode 1).
// Reproducible authoring: carve rooms/corridors, place doors/entities, and the
// ghost Session log, then write the doc-11 JSON. Run: npx vite-node scripts/gen-episode1.ts

import { writeFileSync } from 'node:fs';

const W = 40;
const H = 14;
const tiles: number[] = new Array(W * H).fill(1); // 1 = wall

const carve = (x0: number, y0: number, x1: number, y1: number, v = 0): void => {
  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) tiles[y * W + x] = v;
};

// Rooms (interior floor).
carve(2, 2, 7, 11); //  A  Working Directory (spawn, easter eggs)
carve(11, 2, 17, 11); // B  Hallucination Bots (scanner puzzle)
carve(21, 2, 28, 11); // C  Session Archive (anchor + replayer + locked door)
carve(32, 2, 37, 11); // D  Production (Gate)
// Corridors between rooms at eye level (2 tiles tall).
carve(8, 6, 10, 7); //  A -> B
carve(18, 6, 20, 7); // B -> C
carve(29, 6, 31, 7); // C -> D

const map = {
  id: '1',
  region: 'session-archive',
  palette: 'cool-blue',
  grid: { width: W, height: H, tiles },
  spawn: { at: [3, 6], angle: 0 },
  doors: [
    { at: [8, 6], label: 'main' },
    { at: [18, 6], label: 'feature/exit' },
    // The key puzzle: locked — only the Session ghost opens it.
    { at: [29, 6], label: 'release', locked: true },
    // A false door: only appears in the east wall of room B during distortion.
    { at: [18, 4], label: 'wip/do-not-merge', false: true },
  ],
  entities: [
    // Room A — tone (docs/10).
    { type: 'readme', at: [6, 3], hint: "Sessions replay history. History doesn't hallucinate." },
    { type: 'rubber-duck', at: [3, 9], hint: 'Quack. When lost, replay what actually happened.' },
    // Room B — bots (2 fake, 1 real) crowding a tempting wrong exit.
    { type: 'hallucination-bot', at: [15, 3], real: false },
    { type: 'hallucination-bot', at: [16, 4], real: false },
    { type: 'hallucination-bot', at: [15, 9], real: true },
    // Room C — the Sessions teach moment.
    { type: 'session-anchor', at: [23, 6], sessionId: 'wd-ghost-1' },
    { type: 'pickup', item: 'session-replayer', at: [22, 8] },
    // Room D — the training Gate.
    { type: 'gate-node', at: [35, 6], requiresEvidence: 1, soundDecision: 'promote' },
  ],
  sessions: [
    {
      id: 'wd-ghost-1',
      actions: [
        { t: 0.0, kind: 'move', x: 23.5, y: 6.5, dirX: 1, dirY: 0 },
        { t: 1.4, kind: 'move', x: 26.0, y: 6.5, dirX: 1, dirY: 0 },
        { t: 2.8, kind: 'move', x: 28.5, y: 6.5, dirX: 1, dirY: 0 },
        { t: 3.0, kind: 'say', text: 'the release door — right here.' },
        { t: 3.1, kind: 'door', at: [29, 6] },
        { t: 3.8, kind: 'move', x: 30.5, y: 6.5, dirX: 1, dirY: 0 },
      ],
    },
  ],
  trustStart: 100,
};

const out = 'public/maps/episode1-lost-sessions.json';
writeFileSync(out, JSON.stringify(map, null, 2) + '\n');
console.log(`wrote ${out} (${W}x${H}, ${map.entities.length} entities)`);

import { describe, it, expect } from 'vitest';
import { Trust, tierFor } from '../src/mechanics/trust';

describe('tierFor', () => {
  it('maps values to T0/T1/below (docs/05)', () => {
    expect(tierFor(100)).toBe('T0');
    expect(tierFor(75)).toBe('T0');
    expect(tierFor(74)).toBe('T1');
    expect(tierFor(50)).toBe('T1');
    expect(tierFor(49)).toBe('below');
  });
});

describe('Trust', () => {
  it('starts clamped into [floor,100]', () => {
    expect(new Trust(120).value).toBe(100);
    expect(new Trust(10, 50).value).toBe(50);
  });

  it('clamps at the slice floor so it stays in T0/T1', () => {
    const t = new Trust(100, 50);
    const c = t.change(-90, 'big hit');
    expect(c.value).toBe(50);
    expect(c.tier).toBe('T1');
  });

  it('does not exceed 100', () => {
    const t = new Trust(95);
    expect(t.change(+20).value).toBe(100);
  });

  it('reports tier crossings', () => {
    const t = new Trust(100);
    expect(t.change(-30).crossedTier).toBe(true); // 100 (T0) -> 70 (T1)
    expect(t.change(-5).crossedTier).toBe(false); // 70 -> 65, still T1
    expect(t.change(+20).crossedTier).toBe(true); // 65 -> 85, back to T0
  });
});

import { describe, it, expect } from 'vitest';
import { Evidence } from '../src/mechanics/evidence';

describe('Evidence', () => {
  it('adds unique sources and counts them', () => {
    const e = new Evidence();
    expect(e.add('session:a')).toBe(true);
    expect(e.add('expose:5,3')).toBe(true);
    expect(e.count).toBe(2);
  });

  it('does not double-count the same source', () => {
    const e = new Evidence();
    e.add('session:a');
    expect(e.add('session:a')).toBe(false);
    expect(e.count).toBe(1);
  });

  it('has() checks a threshold', () => {
    const e = new Evidence();
    e.add('a');
    expect(e.has(1)).toBe(true);
    expect(e.has(2)).toBe(false);
  });

  it('spend() consumes tokens or fails cleanly', () => {
    const e = new Evidence();
    e.add('a');
    e.add('b');
    expect(e.spend(3)).toBe(false);
    expect(e.count).toBe(2);
    expect(e.spend(2)).toBe(true);
    expect(e.count).toBe(0);
  });
});

import { describe, it, expect } from 'vitest';
import { evaluateGate } from '../src/mechanics/gates';

describe('evaluateGate (docs/02 §5)', () => {
  it('flags a YOLO merge: promote with zero evidence', () => {
    const o = evaluateGate('promote', 0, 1, 'promote');
    expect(o.yolo).toBe(true);
    expect(o.correct).toBe(false);
    expect(o.trustDelta).toBeLessThan(0);
    expect(o.opened).toBe(true); // training gate always opens
  });

  it('rewards the sound decision backed by enough evidence', () => {
    const o = evaluateGate('promote', 2, 1, 'promote');
    expect(o.correct).toBe(true);
    expect(o.trustDelta).toBeGreaterThan(0);
  });

  it('penalizes insufficient evidence (but not as a YOLO)', () => {
    const o = evaluateGate('reject', 0, 2, 'reject');
    expect(o.yolo).toBe(false);
    expect(o.correct).toBe(false);
    expect(o.trustDelta).toBe(-10);
  });

  it('penalizes an unsound call even with enough evidence', () => {
    const o = evaluateGate('reject', 3, 1, 'promote');
    expect(o.correct).toBe(false);
    expect(o.yolo).toBe(false);
    expect(o.trustDelta).toBe(-5);
  });
});

import { describe, it, expect } from 'vitest';
import { poseAt, duration, discreteEventsBetween, Ghost } from '../src/mechanics/sessions';
import { Recorder } from '../src/mechanics/recorder';
import type { MapSession, Player } from '../src/world/types';

const log: MapSession = {
  id: 'g1',
  actions: [
    { t: 0, kind: 'move', x: 0, y: 0, dirX: 1, dirY: 0 },
    { t: 2, kind: 'move', x: 4, y: 0, dirX: 1, dirY: 0 },
    { t: 1, kind: 'say', text: 'halfway' },
    { t: 1.5, kind: 'door', at: [4, 0] },
  ],
};

describe('poseAt (pure interpolation)', () => {
  it('clamps before the first / after the last keyframe', () => {
    expect(poseAt(log, -1).x).toBe(0);
    expect(poseAt(log, 99).x).toBe(4);
  });

  it('interpolates linearly between keyframes', () => {
    expect(poseAt(log, 1).x).toBeCloseTo(2, 5); // halfway between x0 and x4
  });

  it('duration is the last timestamp', () => {
    expect(duration(log)).toBe(2);
  });
});

describe('discreteEventsBetween', () => {
  it('returns non-move events in (t0,t1]', () => {
    const evs = discreteEventsBetween(log, 0.5, 1.6);
    expect(evs.map((e) => e.kind).sort()).toEqual(['door', 'say']);
  });
});

describe('Ghost', () => {
  it('fires door/say events and completes', () => {
    const doors: [number, number][] = [];
    const says: string[] = [];
    let done = false;
    const g = new Ghost(log, {
      onDoor: (at) => doors.push(at),
      onSay: (t) => says.push(t),
      onDone: () => {
        done = true;
      },
    });
    for (let i = 0; i < 25; i++) g.update(0.1); // 2.5s > duration
    expect(doors).toEqual([[4, 0]]);
    expect(says).toEqual(['halfway']);
    expect(done).toBe(true);
    expect(g.progress()).toBe(1);
  });
});

describe('Recorder round-trip', () => {
  it('captures poses that poseAt can reproduce', () => {
    const rec = new Recorder();
    rec.start('rt');
    const player: Player = { pos: { x: 0, y: 0 }, dir: { x: 1, y: 0 }, plane: { x: 0, y: 0.66 } };
    // Walk +x at 10 units/s for ~1s, sampling each 0.1s tick.
    for (let i = 0; i < 10; i++) {
      player.pos.x += 1;
      rec.sample(0.1, player);
    }
    const out = rec.stop();
    expect(out.id).toBe('rt');
    const moves = out.actions.filter((a) => a.kind === 'move');
    expect(moves.length).toBeGreaterThan(5);
    // The recorded log should reproduce a monotonically increasing x.
    const p0 = poseAt(out, 0);
    const p1 = poseAt(out, duration(out));
    expect(p1.x).toBeGreaterThan(p0.x);
  });
});

